-- Hand-written: drizzle-kit adds a table CHECK by rebuilding `decisions`, and that rebuild drops the add-only and chain triggers from 0003. SQLite accepts the same named CHECKs on an added column, and the snapshot still records them as table checks, so `db:generate` reports no change.
ALTER TABLE `decisions` ADD `recheck_at` text CONSTRAINT "decisions_recheck_at_format" CHECK("decisions"."recheck_at" is strftime('%Y-%m-%dT%H:%M:%fZ', julianday("decisions"."recheck_at"))) CONSTRAINT "decisions_recheck_at_only_for_defer" CHECK(("decisions"."recheck_at" is not null) = ("decisions"."action" in ('defer')));
